#!/usr/bin/env python3
"""Rebuild localized mobile how-to pages from reviewed native screenshot callouts."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
L={
'en':{
'intro':'Follow the numbered circles to complete each goal. These guides describe the 0.2.6 app features; screenshots use fictional identities and sample documents in an isolated capture environment. They do not show real signatures or a real PIN. Tap an image to enlarge it.',
'install':'Install eSemnBun through the available Apple distribution channel from [Downloads](/downloads). Launch the installed app. You need a supported active electronic ID, its correct signing PIN, a compatible wired reader and the appropriate [adapter](/devices). USB-C devices need a suitable USB connection; Lightning devices may need a powered Lightning adapter. NFC signing is not supported.',
'connectTitle':'Connect the reader and insert your card','connectBody':'The signing certificate is read without a PIN. An empty-reader prompt means the reader is detected but the card is not ready. Wait for the holder and expiry before adding a signing request.',
'connectSteps':['Connect the USB reader through the appropriate adapter.','Insert the card when the app reports an empty reader.','Wait for the card holder and expiry to appear.'],
'cardsTitle':'Choose the identity that will sign','cardsBody':'When several cards are connected, swipe the card carousel to centre the intended holder. The selected card is used for the operation. Open Card to check the certificate or re-read the card after reconnecting it. The neutral portrait is an illustration, not a photograph read from the ID.',
'cardsSteps':['Swipe the card carousel to choose the intended holder.','Open Card to inspect the certificate and reader; use the tab overflow if Card is hidden.'],
'cardSteps':['Check the holder, certificate validity and connected reader.','Use re-read after correcting the connection; deleting a saved PIN does not change the physical card PIN.'],
'signTitle':'Add documents and choose a signature format','signBody':'Open Sign and choose files from Files or a cloud provider. Download cloud-only documents first if access fails. You can also send files from another app through its share sheet to the eSemnBun extension. Expand the file list, inspect each name, remove unintended files from its options, and choose the requested format. PDFs use PAdES-T; other files use XAdES. Detached XML must travel with its unchanged original. XAdES-BES has no timestamp, T adds one, and C adds certificate/status references. Enveloping XML includes its source content. Timestamped signing requires the public trust services.',
'signSteps':['Confirm the selected holder before signing.','Choose files, or add more documents to the current queue.','Expand the queue, then open an individual file’s options to choose its format, stamp or removal.','Choose Sign only after reviewing the complete queue.'],
'stampTitle':'Place a visible stamp in a PDF','stampBody':'Open a queued PDF’s options and choose Add/Edit stamp. A visible stamp is optional artwork; the cryptographic signature remains the actual signing proof. Position the stamp away from existing text.',
'stampSteps':['Drag the stamp to move it; drag its corner handles to resize it.','Select the page and choose Off, One page or All pages.','Optionally apply the placement to all queued PDFs, then choose Apply.'],
'approveTitle':'Review the request and authorize signing','approveBody':'For website requests, inspect the requesting origin and the whole document list before allowing the operation. Cancel unexpected requests. For a local batch, review the queued documents and PIN sheet. Each new batch needs approval; a batch session covers only the listed documents and selected card.',
'consentSteps':['Check the requesting website and intended operation.','Review all documents; allow only a request you initiated.'],
'pinSteps':['Check the holder and selected filenames.','Enter the correct QSCD signing PIN in the protected field.','Use Remember PIN only on a trusted personal device; later access requires the offered device authentication.','Choose Sign to authorize, or Cancel to stop.'],
'progressTitle':'Wait for completion and save the signed output','progressBody':'Keep the reader and card connected while signing and obtaining the timestamp. Completion is shown separately from the input queue. Use the available result action, or open Documents and select the completed file, then Share to save it in Files or send it to another app. Share the signed output, not the unsigned source; include the original with detached XML.',
'progressSteps':['Wait for the current signing stage to finish without removing the card.'],
'successSteps':['Check completion and the output name before opening or sharing the result.'],
'errorTitle':'Recover from a failed document','errorBody':'Read the error on the affected item. Keep outputs that already completed and correct the input or connection before starting another deliberate batch. There is no automatic PIN retry. If the PIN is incorrect, stop and confirm the PIN and selected card; after three incorrect attempts the card can be blocked. The app cannot unblock it. Reconnecting cannot repair an invalid PDF.',
'errorSteps':['Read the error on the failed item before making another attempt.'],
'verifyTitle':'Verify a signed PDF and inspect its certificate','verifyBody':'Verification needs a file, not a reader or PIN. In Verify, choose the signed PDF or XML. Expand each signature, then its certificate and technical sections. Check every signature when a file is countersigned. Offline results distinguish document integrity, cryptographic signature, embedded trust and timestamp information; they are not a current revocation check.',
'verifySteps':['Open Verify and add the signed document.','Expand the signature row to read its result and signer.','Open the certificate disclosure for validity, issuer and fingerprint details.'],
'certificateSteps':['Scroll the expanded signature to Certificate details, then review identity, validity and fingerprint separately from document integrity.'],
'xmlTitle':'Supply the original for a detached XML signature','xmlBody':'A detached XML signature cannot prove the original document’s digest until its unchanged source is available. In the incomplete result, use Choose originals and select the matching original files in the system picker. Wait for the result to update. Selecting another file changes the evidence; a missing original alone does not prove modification.',
'xmlSteps':['Read which original is missing.','Choose the unchanged original files and wait for the updated check.'],
'statusTitle':'Understand an unexpected verification result','statusBody':'Invalid means a signature or document-integrity check failed. Unconfirmed trust means the embedded chain is not confirmed; it is different from a proven altered document. Unsigned or unrecognized means no supported signature was found. Do not treat the filename or a green file icon as proof. An inaccessible saved file is unavailable, not necessarily unsigned.',
'invalidSteps':['Read the failed checks; obtain the correct signed file or unchanged original from its sender.'],
'untrustedSteps':['Read the trust warning separately from integrity and signature checks.'],
'unsignedSteps':['Confirm that you chose the signed output, then inspect whether any supported signature was found.'],
'documentsTitle':'Find a saved document and open its signing details','documentsBody':'Open Documents and select a saved item. The signing-details modal uses the same verification presentation as Verify and does not replace the current Verify workspace. Preview opens the content; Share exports the chosen file. If a file has moved or is unreadable, choose it again from its real location.',
'documentsSteps':['Open Documents and select the intended file.','Use the search field to narrow the saved-document list.'],
'detailsSteps':['Review the document’s signing details.','Choose Preview to read the file or Share to save/send it.','Choose Done to return to the library.'],
'historyTitle':'Clear recent history while keeping saved documents','historyBody':'In Documents, switch to History, choose Clear list and confirm. This clears the recent-operations list, not signed files or the saved Documents collection. Return to Documents to find the retained outputs. To delete an exported file, manage it in Files or its storage provider.',
'historySteps':['Switch between Documents and History.','Clear the history list only when you intend to remove those recent records.'],
'browserTitle':'Log in or sign on a website','browserBody':'Open Browser, use Open an address or a saved service, and navigate to the site’s electronic-ID login or signing option. The browser requests desktop presentation for compatible identity-login flows. Keep eSemnBun foregrounded; the mobile connection stops when the app is backgrounded. Check the service and request before approving. The illustration keeps network and hardware inactive, so website navigation controls may be disabled.',
'browserSteps':['Open Browser and check the connection status.','Use the address control to enter the service URL.','Use Services/Bookmarks to open, add or manage a saved address.','Use back, forward and reload while browsing.'],
'browserMore':'To add a bookmark, open Services/Bookmarks → Add bookmark, then set its title, URL and icon and save it. Use Manage bookmarks to edit or remove one. To reset a session, open Clear browser data, select cache, cookies and/or history, then confirm. Clearing cookies can sign you out; it does not clear Documents or saved PINs. A website-side error needs the service’s own support, not repeated PIN attempts.',
'settingsTitle':'Change language, appearance and privacy preferences','settingsBody':'Open Card, then Settings. Choose Romanian, English, Russian or System, and Light, Dark or System appearance. Enable browser PDF stamps only if you want a visible stamp for supported website requests. Normal Demo mode is intentionally labelled; it is for exploration and does not produce real signatures. About shows the installed version and help information. Updates come through the Apple channel used to install the app.',
'settingsSteps':['Choose the interface language and appearance.','Review the optional browser-stamp and document-discovery controls.','Use About for the app version; close Settings with Done.'],
'pinManage':'To manage a saved PIN, open Card for that identity and use Delete saved PIN when available. Saving uses the platform’s protected vault and offered device authentication; deleting the saved copy does not change or unblock the physical card PIN. A different card needs its own PIN.',
'appleTitle':'Use Shortcuts, Siri, Spotlight and Handoff','appleBody':'In Apple Shortcuts, create a shortcut, add an action, search eSemnBun and choose Open Documents, Prepare PDF for Signing or Verify PDF. Supply a PDF to the prepare/verify actions. Prepare opens eSemnBun with the PDF queued; you still review and approve signing in the foreground. Verify returns an offline result and opens the details. PDF input is limited to 32 MiB. Run a configured shortcut from Shortcuts or an available Siri phrase; Siri never receives your card PIN.',
'appleMore':'For document search, enable Find signed documents in Siri and Spotlight in Settings, complete a signed app-owned PDF/XML, then search its filename in Spotlight. The opt-in index exposes filenames and dates, not document bodies, PINs or certificate identity. Current system Open/Search schemas require supported OS/SDK features; suggestions depend on your device, language and system settings. With Handoff enabled on compatible Apple devices, open Documents on one device and use its continuation affordance on the other. Handoff resumes Documents navigation; it does not transfer a PDF, PIN or card session. Siri, Spotlight and Handoff availability should be checked on your installed build; these documentation captures demonstrate app controls rather than a live cross-device result.',
'ipadTitle':'Use iPad windows and Files alongside signing','ipadBody':'This guide uses native iPad captures, not enlarged phone screenshots. The layout follows available window width. In a wider window, keep the card and file controls visible together; in a narrow window, expect compact navigation. Use Files beside eSemnBun to locate documents and choose or drag them where the system permits. If a split window hides controls, enlarge it or scroll before signing. Keep the app active for a website request. The captures below show the native portrait window; they do not establish that every multitasking gesture has been exercised.',
'phoneTitle':'Use a smaller or wider iPhone window','phoneBody':'Portrait uses compact tabs. Rotate the phone or expand a supported device/window when you need more space for the card and files. Scroll to reach document options and the PIN review when the keyboard reduces available space. Device posture and rotation support follow iOS; do not assume a foldable posture is identical to a standard landscape phone.',
'helpTitle':'Get help without sharing secrets','helpBody':'For no reader, check the cable, adapter and power. For an empty reader, reinsert the card and wait. For a repeated card error, stop the operation before reconnecting. For a locked PIN, contact the official card provider. When requesting [support](/support), include app/iOS versions, reader and adapter models and reproduction steps with a fictional sample. Never send your PIN, private identity details or confidential documents.',
'other':'Other guides',
},
'ro':{
'intro':'Urmează cercurile numerotate pentru fiecare obiectiv. Ghidurile descriu funcțiile aplicației 0.2.6; capturile folosesc identități fictive și documente de exemplu într-un mediu izolat. Nu reprezintă semnături reale și nu conțin un PIN real. Atinge imaginea pentru a o mări.',
'install':'Instalează eSemnBun prin canalul Apple disponibil din [Descărcări](/downloads), apoi deschide aplicația instalată. Ai nevoie de un act electronic activ acceptat, PIN-ul corect de semnare, un cititor cu fir compatibil și [adaptorul](/devices) potrivit. Dispozitivele USB-C necesită o conexiune USB adecvată; pentru Lightning poate fi necesar un adaptor alimentat. Semnarea prin NFC nu este disponibilă.',
'connectTitle':'Conectează cititorul și introdu cardul','connectBody':'Certificatul de semnare este citit fără PIN. Mesajul despre cititorul gol indică un cititor detectat, dar fără un card pregătit. Așteaptă afișarea titularului și a valabilității înainte de semnare.',
'connectSteps':['Conectează cititorul USB prin adaptorul potrivit.','Introdu cardul când aplicația indică un cititor gol.','Așteaptă afișarea titularului și a valabilității cardului.'],
'cardsTitle':'Alege identitatea care va semna','cardsBody':'Dacă sunt conectate mai multe carduri, glisează caruselul pentru a centra titularul dorit. Cardul selectat este folosit la operație. Deschide Card pentru certificat sau pentru recitire după reconectare. Portretul neutru este o ilustrație, nu fotografia citită din act.',
'cardsSteps':['Glisează caruselul pentru a alege titularul dorit.','Deschide Card pentru certificat și cititor; folosește meniul filelor dacă această filă este ascunsă.'],
'cardSteps':['Verifică titularul, valabilitatea certificatului și cititorul.','Recitește după corectarea conexiunii; ștergerea PIN-ului salvat nu schimbă PIN-ul cardului.'],
'signTitle':'Adaugă documente și alege formatul semnăturii','signBody':'Deschide Semnează și alege fișiere din Fișiere sau dintr-un furnizor cloud. Descarcă întâi documentele disponibile doar în cloud dacă accesul eșuează. Poți trimite fișiere și din meniul de partajare al altei aplicații către extensia eSemnBun. Extinde lista, verifică numele, elimină fișierele nedorite din opțiunile lor și alege formatul cerut. PDF-urile folosesc PAdES-T; celelalte fișiere folosesc XAdES. XML-ul detașat trebuie păstrat împreună cu originalul nemodificat. XAdES-BES nu are marcă temporală, T o adaugă, iar C include referințe la certificate și stare. XML-ul încorporat include conținutul original. Formatele cu marcă temporală necesită serviciile publice de încredere.',
'signSteps':['Confirmă titularul selectat înainte de semnare.','Alege fișiere sau adaugă alte documente în listă.','Extinde lista și deschide opțiunile unui fișier pentru format, ștampilă sau eliminare.','Apasă Semnează numai după verificarea întregii liste.'],
'stampTitle':'Plasează o ștampilă vizibilă într-un PDF','stampBody':'Deschide opțiunile unui PDF și alege Adaugă/Editează ștampila. Ștampila vizibilă este opțională; dovada semnării rămâne semnătura criptografică. Evită acoperirea textului existent.',
'stampSteps':['Trage ștampila pentru mutare și colțurile pentru redimensionare.','Alege pagina și modul Oprit, O pagină sau Toate paginile.','Opțional, aplică poziția tuturor PDF-urilor din listă, apoi apasă Aplică.'],
'approveTitle':'Verifică cererea și autorizează semnarea','approveBody':'Pentru o cerere de pe un site, verifică originea și întreaga listă de documente înainte de acceptare. Anulează cererile neașteptate. Pentru un lot local, verifică lista și fereastra PIN. Fiecare lot nou necesită aprobare; sesiunea acoperă doar documentele afișate și cardul ales.',
'consentSteps':['Verifică site-ul solicitant și operația dorită.','Verifică toate documentele; acceptă numai o cerere inițiată de tine.'],
'pinSteps':['Verifică titularul și numele fișierelor selectate.','Introdu PIN-ul QSCD corect în câmpul protejat.','Activează memorarea PIN-ului doar pe un dispozitiv personal de încredere; accesul ulterior cere autentificarea oferită de dispozitiv.','Apasă Semnează pentru autorizare sau Anulează pentru oprire.'],
'progressTitle':'Așteaptă finalizarea și salvează rezultatul semnat','progressBody':'Păstrează cititorul și cardul conectate pe durata semnării și a obținerii mărcii temporale. Finalizarea este afișată separat de lista de intrare. Folosește acțiunea rezultatului sau deschide Documente, selectează fișierul finalizat și Partajează pentru salvare în Fișiere ori trimitere către altă aplicație. Trimite rezultatul semnat, nu sursa nesemnată; include originalul pentru XML detașat.',
'progressSteps':['Așteaptă finalizarea etapei curente fără a scoate cardul.'],
'successSteps':['Verifică finalizarea și numele rezultatului înainte de deschidere sau partajare.'],
'errorTitle':'Rezolvă o eroare la un document','errorBody':'Citește eroarea documentului afectat. Păstrează rezultatele deja finalizate și corectează fișierul ori conexiunea înainte de a porni intenționat un lot nou. PIN-ul nu este reîncercat automat. Dacă PIN-ul este greșit, oprește-te și confirmă PIN-ul și cardul selectat; trei încercări greșite pot bloca actul. Aplicația nu îl poate debloca. Reconectarea nu repară un PDF invalid.',
'errorSteps':['Citește eroarea documentului înainte de o nouă încercare.'],
'verifyTitle':'Verifică un PDF semnat și certificatul său','verifyBody':'Verificarea necesită fișierul, nu cititorul sau PIN-ul. În Verifică, alege PDF-ul ori XML-ul semnat. Extinde fiecare semnătură, apoi certificatul și detaliile tehnice. Verifică toate semnăturile unui document contrasemnat. Rezultatele offline separă integritatea, semnătura criptografică, încrederea în lanțul inclus și marca temporală; nu reprezintă verificarea revocării curente.',
'verifySteps':['Deschide Verifică și adaugă documentul semnat.','Extinde rândul semnăturii pentru rezultat și semnatar.','Deschide certificatul pentru valabilitate, emitent și amprentă.'],
'certificateSteps':['Derulează semnătura extinsă la detaliile certificatului, apoi analizează identitatea, valabilitatea și amprenta separat de integritatea documentului.'],
'xmlTitle':'Furnizează originalul pentru XML detașat','xmlBody':'Semnătura XML detașată nu poate confirma amprenta documentului până când originalul nemodificat este disponibil. În rezultatul incomplet, folosește Alege originalele și selectează fișierele corespunzătoare. Așteaptă actualizarea rezultatului. Alegerea altui fișier schimbă dovezile; lipsa originalului nu dovedește singură modificarea.',
'xmlSteps':['Citește ce original lipsește.','Alege originalele nemodificate și așteaptă actualizarea verificării.'],
'statusTitle':'Înțelege un rezultat neașteptat','statusBody':'Invalid înseamnă că verificarea semnăturii sau integrității a eșuat. Încredere neconfirmată înseamnă că lanțul inclus nu este confirmat și diferă de modificarea dovedită. Nesemnat sau nerecunoscut înseamnă că nu a fost găsită o semnătură acceptată. Numele fișierului ori pictograma verde nu sunt dovezi. Un fișier inaccesibil este indisponibil, nu neapărat nesemnat.',
'invalidSteps':['Citește verificările eșuate și cere expeditorului fișierul semnat corect sau originalul nemodificat.'],
'untrustedSteps':['Citește avertismentul de încredere separat de integritate și semnătură.'],
'unsignedSteps':['Confirmă că ai ales rezultatul semnat și verifică dacă există o semnătură acceptată.'],
'documentsTitle':'Găsește un document și deschide detaliile semnării','documentsBody':'Deschide Documente și selectează un element salvat. Fereastra detaliilor folosește aceeași prezentare ca Verifică și nu înlocuiește spațiul de verificare curent. Previzualizare deschide conținutul; Partajează exportă fișierul ales. Dacă fișierul a fost mutat sau nu poate fi citit, selectează-l din locația reală.',
'documentsSteps':['Deschide Documente și selectează fișierul dorit.','Folosește căutarea pentru restrângerea listei.'],
'detailsSteps':['Verifică detaliile semnării documentului.','Alege Previzualizare pentru citire sau Partajează pentru salvare/trimitere.','Apasă Gata pentru revenirea la bibliotecă.'],
'historyTitle':'Șterge istoricul păstrând documentele salvate','historyBody':'În Documente, treci la Istoric, alege Șterge lista și confirmă. Sunt eliminate operațiile recente, nu fișierele semnate sau colecția Documente. Revino la Documente pentru rezultatele păstrate. Șterge un fișier exportat din Fișiere sau din furnizorul său de stocare.',
'historySteps':['Comută între Documente și Istoric.','Șterge istoricul doar dacă dorești eliminarea înregistrărilor recente.'],
'browserTitle':'Autentifică-te sau semnează pe un site','browserBody':'Deschide Browser, folosește Deschide o adresă ori un serviciu salvat și navighează la autentificarea sau semnarea cu act electronic. Browserul solicită prezentarea desktop pentru fluxurile compatibile de autentificare. Păstrează eSemnBun în prim-plan; conexiunea mobilă se oprește în fundal. Verifică serviciul și cererea înainte de aprobare. Ilustrația păstrează rețeaua și hardware-ul inactive, deci comenzile de navigare pot fi dezactivate.',
'browserSteps':['Deschide Browser și verifică starea conexiunii.','Folosește comanda pentru adresă ca să introduci URL-ul serviciului.','Deschide Servicii/Semne de carte pentru adresele salvate.','Folosește înapoi, înainte și reîncărcare în timpul navigării.'],
'browserMore':'Pentru un semn de carte, deschide Servicii/Semne de carte → Adaugă, setează titlul, URL-ul și pictograma, apoi salvează. Gestionarea permite editarea sau eliminarea. Pentru resetarea sesiunii, deschide Șterge datele browserului, alege cache, cookie-uri și/sau istoric și confirmă. Ștergerea cookie-urilor te poate deconecta, dar nu șterge Documente ori PIN-urile salvate. Erorile site-ului necesită asistența serviciului, nu încercări repetate ale PIN-ului.',
'settingsTitle':'Schimbă limba, aspectul și confidențialitatea','settingsBody':'Deschide Card, apoi Setări. Alege Română, English, Русский ori Sistem și tema Luminoasă, Întunecată ori Sistem. Activează ștampilele PDF din browser doar dacă le dorești pentru cererile acceptate. Modul demonstrativ obișnuit este etichetat intenționat și nu produce semnături reale. Despre afișează versiunea și informațiile utile. Actualizările vin prin canalul Apple folosit la instalare.',
'settingsSteps':['Alege limba interfeței și tema.','Verifică opțiunile pentru ștampilă în browser și descoperirea documentelor.','Folosește Despre pentru versiune și Gata pentru închiderea setărilor.'],
'pinManage':'Pentru un PIN memorat, deschide Card pentru identitatea respectivă și Șterge PIN-ul salvat când opțiunea este disponibilă. Memorarea folosește seiful protejat al platformei și autentificarea dispozitivului; ștergerea copiei nu schimbă și nu deblochează PIN-ul fizic. Un alt card necesită propriul PIN.',
'appleTitle':'Folosește Scurtături, Siri, Spotlight și Handoff','appleBody':'În aplicația Apple Scurtături, creează o scurtătură, adaugă o acțiune, caută eSemnBun și alege Deschide Documente, Pregătește PDF pentru semnare ori Verifică PDF. Oferă un PDF acțiunilor de pregătire/verificare. Pregătirea deschide aplicația cu PDF-ul în listă; verifici și aprobi semnarea în prim-plan. Verificarea returnează rezultatul offline și deschide detaliile. Limita PDF este 32 MiB. Rulează scurtătura din aplicație ori printr-o expresie Siri disponibilă; Siri nu primește PIN-ul cardului.',
'appleMore':'Pentru căutare, activează Găsește documentele semnate în Siri și Spotlight din Setări, finalizează un PDF/XML semnat deținut de aplicație și caută numele în Spotlight. Indexul opțional expune numele și datele, nu conținutul, PIN-ul ori identitatea certificatului. Schemele sistem Open/Search necesită funcțiile OS/SDK acceptate; sugestiile depind de dispozitiv, limbă și configurare. Cu Handoff activ pe dispozitive Apple compatibile, deschide Documente pe unul și continuă de pe celălalt. Handoff reia navigarea către Documente; nu transferă PDF-ul, PIN-ul sau sesiunea cardului. Verifică disponibilitatea Siri, Spotlight și Handoff în versiunea instalată; capturile arată comenzile aplicației, nu un rezultat real între dispozitive.',
'ipadTitle':'Folosește ferestrele iPad și Fișiere alături de semnare','ipadBody':'Ghidul folosește capturi iPad native, nu imagini de telefon mărite. Aspectul urmează lățimea ferestrei. Într-o fereastră largă, cardul și comenzile fișierelor pot rămâne vizibile împreună; într-una îngustă, navigarea devine compactă. Deschide Fișiere alături de eSemnBun și alege sau trage documentele unde sistemul permite. Mărește fereastra ori derulează dacă o comandă este ascunsă. Păstrează aplicația activă pentru cererile web. Capturile arată fereastra portret nativă, nu verificarea tuturor gesturilor de multitasking.',
'phoneTitle':'Folosește o fereastră iPhone mai mică sau mai largă','phoneBody':'În portret sunt folosite file compacte. Rotește telefonul sau extinde dispozitivul/fereastra acceptată pentru mai mult spațiu la card și fișiere. Derulează pentru opțiuni și verificarea PIN când tastatura reduce spațiul. Postura și rotația depind de iOS; o postură pliabilă nu este identică automat cu un telefon în peisaj.',
'helpTitle':'Cere ajutor fără a trimite secrete','helpBody':'Fără cititor: verifică firul, adaptorul și alimentarea. Cititor gol: reintrodu cardul și așteaptă. Eroare repetată a cardului: oprește operația înainte de reconectare. PIN blocat: contactează furnizorul oficial. Pentru [asistență](/support), include versiunile aplicației/iOS, modelele cititorului și adaptorului și pașii cu un exemplu fictiv. Nu trimite PIN-ul, date private de identitate sau documente confidențiale.',
'other':'Alte ghiduri',
},
'ru':{
'intro':'Следуйте пронумерованным кружкам для каждой цели. Руководства описывают функции приложения 0.2.6; снимки получены в изолированном режиме с вымышленными данными и примерами документов. Реальных подписей и PIN на них нет. Нажмите изображение для увеличения.',
'install':'Установите eSemnBun через доступный канал Apple на странице [Загрузки](/downloads) и откройте установленное приложение. Потребуются поддерживаемое активное электронное удостоверение, правильный PIN подписи, совместимый проводной считыватель и [адаптер](/devices). Для USB-C нужно подходящее USB-подключение; для Lightning может потребоваться адаптер с питанием. Подписание через NFC не поддерживается.',
'connectTitle':'Подключите считыватель и вставьте карту','connectBody':'Сертификат подписи читается без PIN. Сообщение о пустом считывателе означает, что устройство обнаружено, но карта ещё не готова. Дождитесь имени владельца и срока действия перед подписанием.',
'connectSteps':['Подключите USB-считыватель через подходящий адаптер.','Вставьте карту, когда приложение сообщает о пустом считывателе.','Дождитесь имени владельца и срока действия карты.'],
'cardsTitle':'Выберите владельца подписи','cardsBody':'Если подключено несколько карт, проведите по карусели, чтобы нужный владелец оказался в центре. Для операции используется выбранная карта. Откройте Карту для сертификата или повторного чтения после подключения. Нейтральный портрет — иллюстрация, а не фотография из удостоверения.',
'cardsSteps':['Проведите по карусели и выберите нужного владельца.','Откройте Карту для сертификата и считывателя; используйте меню дополнительных вкладок, если Карта скрыта.'],
'cardSteps':['Проверьте владельца, срок сертификата и считыватель.','Повторите чтение после исправления подключения; удаление сохранённого PIN не меняет PIN карты.'],
'signTitle':'Добавьте документы и выберите формат подписи','signBody':'Откройте Подписать и выберите файлы в Файлах или облачном хранилище. Если доступ к облачному документу не удался, сначала загрузите его. Можно также отправить файлы из меню «Поделиться» другого приложения в расширение eSemnBun. Разверните список, проверьте имена, удалите лишнее через параметры файла и выберите нужный формат. PDF использует PAdES-T, другие файлы — XAdES. Отделённый XML нужно хранить с неизменённым оригиналом. XAdES-BES не содержит метку времени, T добавляет её, C включает ссылки на сертификаты и статус. Включённый XML содержит исходный документ. Форматы с меткой времени требуют публичных служб доверия.',
'signSteps':['Проверьте выбранного владельца перед подписанием.','Выберите файлы или добавьте документы в текущий список.','Разверните список и откройте параметры файла для формата, штампа или удаления.','Нажмите Подписать после проверки всего списка.'],
'stampTitle':'Разместите видимый штамп в PDF','stampBody':'Откройте параметры PDF и выберите добавление или редактирование штампа. Видимый штамп необязателен; доказательством подписи остаётся криптографическая подпись. Не закрывайте существующий текст.',
'stampSteps':['Перемещайте штамп перетаскиванием, меняйте размер за углы.','Выберите страницу и режим Выкл., Одна страница или Все страницы.','При необходимости примените размещение ко всем PDF в очереди, затем нажмите Применить.'],
'approveTitle':'Проверьте запрос и разрешите подписание','approveBody':'Для запроса сайта проверьте источник и весь список документов перед разрешением. Отменяйте неожиданные запросы. Для локального пакета проверьте очередь и окно PIN. Каждый новый пакет требует подтверждения; сеанс относится только к показанным документам и выбранной карте.',
'consentSteps':['Проверьте сайт-источник и нужную операцию.','Проверьте все документы и разрешайте только начатый вами запрос.'],
'pinSteps':['Проверьте владельца и выбранные имена файлов.','Введите правильный QSCD PIN в защищённое поле.','Сохраняйте PIN только на доверенном личном устройстве; последующий доступ требует предлагаемую устройством аутентификацию.','Нажмите Подписать для разрешения или Отмена для остановки.'],
'progressTitle':'Дождитесь завершения и сохраните подписанный результат','progressBody':'Не отключайте карту и считыватель во время подписания и получения метки времени. Завершение показывается отдельно от входной очереди. Используйте действие результата либо откройте Документы, выберите готовый файл и Поделиться для сохранения в Файлах или отправки другому приложению. Передавайте подписанный результат, а не исходник; для отделённого XML добавляйте оригинал.',
'progressSteps':['Дождитесь завершения текущего этапа, не вынимая карту.'],
'successSteps':['Проверьте завершение и имя результата перед открытием или отправкой.'],
'errorTitle':'Устраните ошибку отдельного документа','errorBody':'Прочитайте ошибку проблемного файла. Сохраните уже готовые результаты и исправьте входной файл или подключение перед намеренным запуском нового пакета. Автоматического повтора PIN нет. При неверном PIN остановитесь и проверьте PIN и выбранную карту: три ошибки могут заблокировать удостоверение. Приложение не может его разблокировать. Переподключение не исправит повреждённый PDF.',
'errorSteps':['Прочитайте ошибку файла перед новой попыткой.'],
'verifyTitle':'Проверьте подписанный PDF и его сертификат','verifyBody':'Для проверки нужен файл, а не считыватель или PIN. В Проверке выберите подписанный PDF или XML. Разверните каждую подпись, затем сертификат и технические сведения. При нескольких подписях изучите каждую. Офлайн-результат различает целостность документа, криптографическую подпись, доверие встроенной цепочке и метку времени; это не проверка текущего отзыва сертификата.',
'verifySteps':['Откройте Проверку и добавьте подписанный документ.','Разверните строку подписи для результата и подписанта.','Откройте сертификат для срока, издателя и отпечатка.'],
'certificateSteps':['Прокрутите раскрытую подпись до сведений о сертификате и изучите владельца, срок и отпечаток отдельно от целостности документа.'],
'xmlTitle':'Укажите оригинал для отделённой XML-подписи','xmlBody':'Отделённая XML-подпись не подтверждает хеш оригинала, пока неизменённый исходник недоступен. В неполном результате выберите оригиналы через системное окно файлов и дождитесь обновления. Выбор другого файла меняет проверяемые данные; отсутствие оригинала само по себе не доказывает изменение.',
'xmlSteps':['Прочитайте, какого оригинала не хватает.','Выберите неизменённые оригиналы и дождитесь обновления проверки.'],
'statusTitle':'Поймите неожиданный результат проверки','statusBody':'Недействительно означает сбой проверки подписи или целостности. Неподтверждённое доверие означает, что встроенная цепочка не подтверждена; это не то же самое, что доказанное изменение файла. Без подписи или нераспознано означает отсутствие поддерживаемой подписи. Имя файла или зелёный значок не являются доказательством. Недоступный сохранённый файл не обязательно неподписан.',
'invalidSteps':['Прочитайте неудавшиеся проверки и запросите у отправителя правильный подписанный файл или неизменённый оригинал.'],
'untrustedSteps':['Изучите предупреждение о доверии отдельно от целостности и подписи.'],
'unsignedSteps':['Убедитесь, что выбран подписанный результат, и проверьте наличие поддерживаемой подписи.'],
'documentsTitle':'Найдите документ и откройте сведения о подписи','documentsBody':'Откройте Документы и выберите сохранённый элемент. Модальное окно сведений использует ту же проверку, что вкладка Проверка, и не заменяет её текущие файлы. Просмотр открывает содержимое, Поделиться экспортирует выбранный файл. Перемещённый или нечитаемый файл выберите снова из его фактического расположения.',
'documentsSteps':['Откройте Документы и выберите нужный файл.','Используйте поиск для сужения списка.'],
'detailsSteps':['Изучите сведения о подписи документа.','Выберите Просмотр для чтения или Поделиться для сохранения/отправки.','Нажмите Готово для возврата к библиотеке.'],
'historyTitle':'Очистите историю, сохранив документы','historyBody':'В Документах перейдите в Историю, выберите очистку списка и подтвердите. Удаляется список недавних операций, а не подписанные файлы или коллекция Документов. Вернитесь в Документы для сохранённых результатов. Экспортированный файл удаляется в Файлах или его хранилище.',
'historySteps':['Переключайтесь между Документами и Историей.','Очистите историю только для удаления записей о недавних операциях.'],
'browserTitle':'Войдите или подпишите на сайте','browserBody':'Откройте Браузер, укажите адрес или сохранённый сервис и перейдите к входу либо подписанию с электронным удостоверением. Для совместимых сценариев входа браузер запрашивает настольное представление. Держите eSemnBun на переднем плане: в фоне мобильное соединение останавливается. Проверьте сервис и запрос перед разрешением. Иллюстрация отключает сеть и оборудование, поэтому элементы навигации могут быть недоступны.',
'browserSteps':['Откройте Браузер и проверьте состояние соединения.','Используйте кнопку адреса для URL сервиса.','Откройте Сервисы/Закладки для сохранённых адресов.','Используйте назад, вперёд и обновление при просмотре сайта.'],
'browserMore':'Чтобы добавить закладку, откройте Сервисы/Закладки → Добавить, задайте название, URL и значок и сохраните. Управление закладками позволяет менять и удалять их. Для сброса сеанса откройте очистку данных браузера, выберите кеш, cookie и/или историю и подтвердите. Удаление cookie может выйти из учётной записи, но не удаляет Документы или сохранённые PIN. Ошибки сайта решайте с его поддержкой, без повторных попыток PIN.',
'settingsTitle':'Измените язык, оформление и приватность','settingsBody':'Откройте Карту, затем Настройки. Выберите Română, English, Русский или системный язык, светлую, тёмную или системную тему. Включайте PDF-штампы браузера только при необходимости для поддерживаемых запросов сайта. Обычный демонстрационный режим намеренно помечен и не создаёт реальных подписей. Раздел О приложении показывает версию и справочные данные. Обновления приходят через канал Apple, использованный при установке.',
'settingsSteps':['Выберите язык интерфейса и оформление.','Проверьте необязательные настройки штампа браузера и обнаружения документов.','Узнайте версию в О приложении; закройте настройки кнопкой Готово.'],
'pinManage':'Для сохранённого PIN откройте Карту нужного владельца и удалите сохранённый PIN, если действие доступно. Сохранение использует защищённое хранилище платформы и аутентификацию устройства; удаление копии не меняет и не разблокирует физический PIN. Другой карте нужен собственный PIN.',
'appleTitle':'Используйте Команды, Siri, Spotlight и Handoff','appleBody':'В Apple Командах создайте команду, добавьте действие, найдите eSemnBun и выберите Открыть Документы, Подготовить PDF для подписи или Проверить PDF. Передайте PDF действиям подготовки или проверки. Подготовка открывает eSemnBun с PDF в очереди; проверка и разрешение подписи остаются на переднем плане. Проверка возвращает офлайн-результат и открывает сведения. Размер PDF ограничен 32 МиБ. Запускайте настроенную команду из приложения либо доступной фразой Siri; Siri не получает PIN карты.',
'appleMore':'Для поиска включите поиск подписанных документов в Siri и Spotlight в Настройках, завершите подписанный PDF/XML внутри приложения и найдите его имя в Spotlight. Индексирование по согласию раскрывает имена и даты, а не содержимое, PIN или данные владельца сертификата. Системные схемы Open/Search требуют поддерживаемых функций OS/SDK; предложения зависят от устройства, языка и настроек. При включённом Handoff на совместимых устройствах Apple откройте Документы на одном и продолжите на другом. Handoff возобновляет переход к Документам, не передаёт PDF, PIN или сеанс карты. Проверяйте доступность Siri, Spotlight и Handoff в установленной сборке; снимки показывают настройки приложения, а не реальный межустройственный результат.',
'ipadTitle':'Используйте окна iPad и Файлы рядом с подписанием','ipadBody':'Здесь используются родные снимки iPad, а не увеличенные изображения телефона. Интерфейс следует ширине окна. В широком окне карта и файловые действия могут оставаться рядом; в узком навигация компактнее. Откройте Файлы рядом с eSemnBun и выбирайте или перетаскивайте документы там, где это разрешает система. Увеличьте окно или прокрутите, если действие скрыто. Для запроса сайта приложение должно быть активно. Снимки показывают родное портретное окно, а не проверку всех жестов многозадачности.',
'phoneTitle':'Используйте более узкое или широкое окно iPhone','phoneBody':'В портретном режиме используются компактные вкладки. Поверните телефон или расширьте поддерживаемое устройство/окно для большего места у карты и файлов. Прокрутите к параметрам документа и проверке PIN, когда клавиатура уменьшает доступное место. Положение и поворот зависят от iOS; складной режим не обязательно идентичен обычному альбомному телефону.',
'helpTitle':'Получите помощь без передачи секретов','helpBody':'Нет считывателя — проверьте кабель, адаптер и питание. Пустой считыватель — вставьте карту снова и подождите. Повторная ошибка карты — остановите операцию перед переподключением. Заблокированный PIN — обратитесь к официальному поставщику карты. Для [поддержки](/support) укажите версии приложения/iOS, модели считывателя и адаптера и шаги с вымышленным примером. Не отправляйте PIN, личные сведения удостоверения или конфиденциальные документы.',
'other':'Другие руководства',
}}
# Coordinates reviewed against clean native captures; per-form overrides are applied below.
COORDS={
'connect':[(25,28)],'empty-reader':[(25,29)],'sign':[(31,27),(29,69),(78,53),(78,9)],
'cards':[(28,27),(90,94)],'card':[(6,50),(90,9)],'stamp':[(30,61),(25,86),(87,12)],
'consent':[(16,52),(86,91)],'pin':[(49,23),(8,34),(86,40),(88,63)],
'progress':[(10,45)],'success':[(35,49)],'file-error':[(50,72)],
'verify':[(26,24),(8,48)],'certificate':[(9,87)],'incomplete':[(8,50),(8,55)],
'invalid':[(14,41)],'untrusted':[(14,41)],'unsigned':[(14,41)],
'documents':[(14,40),(10,22)],'details':[(12,31),(8,44),(90,12)],
'history':[(91,29),(80,9)],'browser':[(8,15),(88,9),(77,9),(18,87)],
'settings':[(95,29),(86,65),(68,12)]}
IPAD_COORDS={
'connect':[(10,16)],'empty-reader':[(10,17)],'sign':[(12,15),(79,30),(93,16),(10,28)],
'cards':[(20,18),(73,5)],'card':[(7,37),(95,5)],'stamp':[(42,55),(25,70),(79,26)],
'consent':[(20,50),(79,74)],'pin':[(50,19),(30,27),(73,31),(94,70)],
'progress':[(9,33)],'success':[(9,29)],'file-error':[(47,19)],
'verify':[(37,15),(11,33)],'certificate':[(13,59)],'incomplete':[(20,33),(10,35)],
'invalid':[(13,27)],'untrusted':[(13,27)],'unsigned':[(13,27)],
'documents':[(7,22),(97,5)],'details':[(22,40),(19,49),(80,26)],
'history':[(74,14),(91,5)],'browser':[(5,8),(97,5),(91,5),(6,97)],
'settings':[(19,38),(78,63),(80,26)]}
IPAD_CROPS={
'connect':(0,0,1,.29),'empty-reader':(0,0,1,.29),'sign':(0,0,1,.40),
'cards':(0,0,1,.42),'progress':(0,0,1,.40),'file-error':(0,0,1,.44),
'success':(0,0,1,.70),'verify':(0,0,1,.41),'invalid':(0,0,1,.41),
'untrusted':(0,0,1,.41),'incomplete':(0,0,1,.50),'unsigned':(0,0,1,.37),
'documents':(0,0,1,.43),'history':(0,0,1,.43),
'details':(.15,.22,.85,.56),'consent':(.15,.46,.85,.78),
'settings':(.15,.23,.85,.80),'stamp':(.15,.23,.85,.80)}
# Trim repeated instructions: the following native image shows the next state.
for lang in L:
 L[lang]['emptySteps']=[L[lang]['connectSteps'][1]]
 L[lang]['connectSteps']=[L[lang]['connectSteps'][0]]
 L[lang]['verifySteps']=L[lang]['verifySteps'][:2]

def shot(form,lang,name,stepkey,caption=None):
 if caption is None and form=='ipad' and name in IPAD_CROPS:
  caption={'en':'Native iPad portrait capture; unused canvas or surrounding sheet space cropped for legibility.','ro':'Captură iPad nativă în portret; spațiul liber ori împrejurimile ferestrei au fost decupate pentru lizibilitate.','ru':'Родной портретный снимок iPad; пустое поле или пространство вокруг окна обрезано для читаемости.'}[lang]
 d=L[lang];coords=list((IPAD_COORDS if form=='ipad' else COORDS)[name]);steps=[]
 if form=='ipad' and lang=='ru' and name=='cards':coords[1]=(83,5)
 for i,text in enumerate(d[stepkey]):
  item={'text':text}
  if i<len(coords):
   x,y=coords[i]
   if form=='ipad' and name in IPAD_CROPS:
    l,t,r,b=IPAD_CROPS[name];x=(x-100*l)/(r-l);y=(y-100*t)/(b-t)
   item.update(x=round(x,1),y=round(y,1))
  steps.append(item)
 return f'<GuideScreenshot src="/img/guide/{form}/{lang}/{name}.png" alt="{d[stepkey][0]}"'+(' caption='+json.dumps(caption,ensure_ascii=False) if caption else '')+' steps={'+json.dumps(steps,ensure_ascii=False)+'} />\n'

def build(form,lang):
 d=L[lang];title='iPhone' if form=='iphone' else 'iPad';out=f'---\ntitle: {title}\n---\n\nimport GuideScreenshot from \'@site/src/components/GuideScreenshot\';\n\n# {title}\n\n{d["intro"]}\n\n{d["install"]}\n'
 def section(key):return f'\n## {d[key+"Title"]}\n\n{d[key+"Body"]}\n\n'
 out+=section('connect')+shot(form,lang,'connect','connectSteps')+shot(form,lang,'empty-reader','emptySteps')
 out+=section('cards')+shot(form,lang,'cards','cardsSteps')+shot(form,lang,'card','cardSteps')
